    }

    /**
     * @dev Returns the owner address associated with this strategy instance.
     */
    function getOwner() external view override returns (address ownerAddress) {
        return proxyOwner;
    }

    function getCoinType() external pure returns (CoinType) {
        return CoinType.MEME;
    }

    function getPositionDirection() external pure returns (PositionDirection) {
        return PositionDirection.SHORT;
    }

    function getLeverage() external pure returns (uint32) {
        return 5; // 5x leverage for aggressive short strategy
    }

    function getPortfolioIndices() external view returns (uint16[] memory) {
        uint16[] memory indices = new uint16[](strategyAssets.length);
        for (uint i = 0; i < strategyAssets.length; i++) {
            indices[i] = assetToIndex[strategyAssets[i]];
        }
        return indices;
    }

    /**
     * @dev Opens short positions according to the strategy allocation
     */
    function openPositions(
        address holder,
        uint64 usdcAmount
    ) external returns (uint16[] memory indices, bool[] memory isBuy, uint64[] memory sz) {
        require(msg.sender == address(this), "DumpStrategy: Direct call not allowed");
        require(proxyOwner != address(0), "DumpStrategy: Not initialized");
        
        uint256 numAssets = strategyAssets.length;
        indices = new uint16[](numAssets);
        isBuy = new bool[](numAssets);
        sz = new uint64[](numAssets);

        // Distribution for meme assets: DOGE/SHIB 30% each, PEPE/BONK/WIF 13.33% each
        for (uint i = 0; i < numAssets; i++) {
            indices[i] = assetToIndex[strategyAssets[i]];
            isBuy[i] = false; // Always sell for short positions
            
            if (i < 2) { // DOGE and SHIB get 30% each
                sz[i] = (usdcAmount * 30) / 100;
            } else { // PEPE, BONK, and WIF split the remaining 40%
                sz[i] = (usdcAmount * 40) / (100 * 3);
            }
        }

        return (indices, isBuy, sz);
    }

    // --- Internal Helper Functions ---
    // TODO: Add helpers for DEX shorting/covering interactions, price fetching, etc. specific to meme coins.

    // Helper function for absolute difference
    function absDiff(uint256 a, uint256 b) internal pure returns (uint256) {
        return a > b ? a - b : b - a;
    }
}

contracts/FactoryContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./StrategyProxy.sol";

/**
 * @title FactoryContract
 * @dev Deploys individual StrategyProxy contracts for users based on selected strategies.
 * Manages the addresses of the underlying strategy implementation contracts.
 */
contract FactoryContract {
    address public owner;
    address public feeRecipient; // Address where platform fees from strategies are sent

    // Mapping from strategy name (bytes32 for gas efficiency) to implementation address
    mapping(bytes32 => address) public strategyImplementations;

    // Optional: Keep track of proxies deployed by a user
    mapping(address => address[]) public userProxies;
    // Optional: Keep track of all deployed proxies
    address[] public allProxies;

    event StrategyImplementationSet(bytes32 indexed strategyName, address indexed implementationAddress);
    event FeeRecipientSet(address indexed newFeeRecipient);
    event ProxyDeployed(
        address indexed user,
        bytes32 indexed strategyName,
        address proxyAddress,
        address implementationAddress
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "FactoryContract: Caller is not the owner");
        _;
    }

    constructor(address _initialFeeRecipient) {
        owner = msg.sender;
        require(_initialFeeRecipient != address(0), "FactoryContract: Initial fee recipient cannot be zero");
        feeRecipient = _initialFeeRecipient;
        emit FeeRecipientSet(_initialFeeRecipient);
    }

    /**
     * @dev Sets or updates the address of a strategy implementation contract.
     * @param _strategyName The name of the strategy (e.g., "MEGA", "DOWN").
     * @param _implementationAddress The address of the deployed implementation contract.
     */
    function setStrategyImplementation(string calldata _strategyName, address _implementationAddress) external onlyOwner {
        require(_implementationAddress != address(0), "FactoryContract: Implementation address cannot be zero");
        bytes32 strategyNameBytes = keccak256(abi.encodePacked(_strategyName));
        strategyImplementations[strategyNameBytes] = _implementationAddress;
        emit StrategyImplementationSet(strategyNameBytes, _implementationAddress);
    }

    /**
     * @dev Updates the address where platform fees are collected.
     * @param _newFeeRecipient The new address for fee collection.
     */
    function setFeeRecipient(address _newFeeRecipient) external onlyOwner {
        require(_newFeeRecipient != address(0), "FactoryContract: New fee recipient cannot be zero");
        feeRecipient = _newFeeRecipient;
        emit FeeRecipientSet(_newFeeRecipient);
    }

    /**
     * @dev Deploys a new StrategyProxy instance for the caller for a specific strategy.
     * @param _strategyName The name of the strategy to deploy a proxy for.
     * @return proxyAddress The address of the newly deployed StrategyProxy.
     */
    function deployProxy(string calldata _strategyName) external returns (address proxyAddress) {
        bytes32 strategyNameBytes = keccak256(abi.encodePacked(_strategyName));
        address implementationAddress = strategyImplementations[strategyNameBytes];
        require(implementationAddress != address(0), "FactoryContract: Strategy implementation not set");

        // Deploy the StrategyProxy using create2 for deterministic addresses or standard create
        // Using standard 'new' for simplicity here
        StrategyProxy newProxy = new StrategyProxy(msg.sender, implementationAddress, feeRecipient);
        proxyAddress = address(newProxy);

        // Optional: Track deployed proxies
        userProxies[msg.sender].push(proxyAddress);
        allProxies.push(proxyAddress);

        emit ProxyDeployed(msg.sender, strategyNameBytes, proxyAddress, implementationAddress);
        return proxyAddress;
    }

    // --- View Functions ---

    /**
     * @dev Gets the implementation address for a given strategy name.
     * @param _strategyName The name of the strategy.
     * @return The address of the implementation contract.
     */
    function getImplementation(string calldata _strategyName) external view returns (address) {
        return strategyImplementations[keccak256(abi.encodePacked(_strategyName))];
    }

    /**
     * @dev Gets the list of proxy addresses deployed by a specific user.
     * @param _user The address of the user.
     * @return An array of proxy addresses.
     */
    function getUserProxies(address _user) external view returns (address[] memory) {
        return userProxies[_user];
    }

    /**
     * @dev Gets the total number of proxies deployed by this factory.
     * @return The count of all deployed proxies.
     */
    function getAllProxiesCount() external view returns (uint256) {
        return allProxies.length;
    }

    /**
     * @dev Transfers ownership of the factory contract.
     * @param newOwner The address of the new owner.
     */
    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "FactoryContract: New owner cannot be zero address");
        owner = newOwner;
    }
}

contracts/interface/IStrategy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

// Enums for strategy classification
enum CoinType { MAJOR, MEME }
enum PositionDirection { LONG, SHORT }

// Basic struct to represent a trade record
struct Trade {
    uint256 timestamp;
    string tradeType; // e.g., "Entry", "Exit", "Add", "Reduce", "Rebalance"
    address assetIn; // Address of the asset being spent/sold
    uint256 amountIn;
    address assetOut; // Address of the asset being received/bought
    uint256 amountOut;
    uint256 feeAmount; // Fee paid for this trade
    address feeAsset; // Asset the fee was paid in
}

// Basic struct to represent a current holding
struct Holding {
    address asset; // Address of the asset held
    uint256 amount; // Amount of the asset held
    uint256 valueUsd; // Optional: Current value in USD (or other base currency)
}

interface IStrategy {
    /**
     * @dev Increases the user's position in the strategy.
     * Called via delegatecall from StrategyProxy.
     * Should handle DEX interactions, fee calculation, and state updates.
     * @param amount Amount of collateral (e.g., USDC) to add.
     * @param feeRecipient Address to send the calculated platform fee.
     */
    function addLiquidity(uint256 amount, address feeRecipient) external;

    /**
     * @dev Decreases the user's position in the strategy.
     * Called via delegatecall from StrategyProxy.
     * Should handle DEX interactions, fee calculation, and state updates.
     * @param amount Amount of collateral (e.g., USDC) equivalent to remove.
     * @param feeRecipient Address to send the calculated platform fee.
     */
    function removeLiquidity(uint256 amount, address feeRecipient) external;

    /**
     * @dev Executes periodic strategy logic, like rebalancing.
     * Called via delegatecall from StrategyProxy.
     */
    function execute() external;

    /**
     * @dev Calculates and returns the current profit or loss for the user's position.
     * Called via staticcall from StrategyProxy.
     * @return pnl The current profit or loss (can be negative).
     */
    function getProfitLoss() external view returns (int256 pnl);

    /**
     * @dev Returns the history of trades executed for the user's position.
     * Called via staticcall from StrategyProxy.
     * @return history An array of Trade structs.
     */
    function getTradeHistory() external view returns (Trade[] memory history);

    /**
     * @dev Returns the current collateral balance managed by the strategy for the proxy.
     * Note: The proxy also holds its own balance; this reflects the strategy's view.
     * Called via staticcall from StrategyProxy.
     * @return balance The current collateral balance.
     */
    function getBalance() external view returns (uint256 balance);

    /**
     * @dev Returns the current assets held by the strategy for the user's position.
     * Called via staticcall from StrategyProxy.
     * @return holdings An array of Holding structs.
     */
    function getHoldings() external view returns (Holding[] memory holdings);

    /**
     * @dev Returns the owner address associated with this strategy instance (via the proxy).
     * Called via staticcall from StrategyProxy.
     * @return ownerAddress The address of the user owning the proxy.
     */
    function getOwner() external view returns (address ownerAddress);

    /**
     * @dev Returns array of portfolio indices used by this strategy
     */
    function getPortfolioIndices() external view returns (uint16[] memory);

    /**
     * @dev Returns the type of coins this strategy trades (MAJOR or MEME)
     */
    function getCoinType() external view returns (CoinType);

    /**
     * @dev Returns whether this strategy takes LONG or SHORT positions
     */
    function getPositionDirection() external view returns (PositionDirection);

    /**
     * @dev Returns the leverage factor used by this strategy
     */
    function getLeverage() external view returns (uint32);

    /**
     * @dev Opens positions according to the strategy allocation
     * @param holder The address holding the position
     * @param usdcAmount The amount of USDC to use for opening positions
     * @return indices Array of asset indices to trade
     * @return isBuy Array of booleans indicating buy (true) or sell (false) for each position
     * @return sz Array of position sizes in USDC
     */
    function openPositions(
        address holder,
        uint64 usdcAmount
    ) external returns (uint16[] memory indices, bool[] memory isBuy, uint64[] memory sz);

    // Note: initialize() function is expected in implementations but not part of the runtime interface called by proxy delegatecall.
}

