}

contract MockHyperliquidDEX is IHyperliquidRouter {
    // Mock storage for asset prices
    mapping(uint16 => uint256) public prices;
    
    constructor() {
        // Initialize with same indices as used in ZoomStrategy
        prices[0] = 0.1e6;    // DOGE mock price in USDC (index 0)
        prices[1] = 0.01e6;   // SHIB mock price in USDC (index 1)
        prices[2] = 0.001e6;  // PEPE mock price in USDC (index 2)
        prices[3] = 0.0001e6; // BONK mock price in USDC (index 3)
        prices[4] = 0.05e6;   // WIF mock price in USDC  (index 4)
    }

    // IHyperliquidRouter implementation
    function getAssetPrice(uint16 assetIndex) external view override returns (uint256) {
        require(prices[assetIndex] > 0, "DEX: Invalid asset index");
        return prices[assetIndex];
    }

    // Mock function for swapping tokens
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        uint16[] calldata path,
        address to,
        uint256 deadline
    ) external returns (uint256[] memory amounts) {
        require(deadline >= block.timestamp, "DEX: Expired");
        amounts = new uint256[](path.length);
        amounts[0] = amountIn;
        // Mock the swap calculation using prices
        for (uint i = 1; i < path.length; i++) {
            amounts[i] = (amounts[i-1] * prices[path[i-1]]) / prices[path[i]];
        }
        require(amounts[amounts.length - 1] >= amountOutMin, "DEX: Insufficient output amount");
        return amounts;
    }

    // Mock function for getting the current price of an asset (legacy method)
    function getPrice(uint16 assetIndex) external view returns (uint256) {
        return this.getAssetPrice(assetIndex);
    }

    // Mock function for margin trading
    function openMarginPosition(
        uint16 assetIndex,
        bool isLong,
        uint256 collateralAmount,
        uint32 leverage
    ) external returns (uint256 positionSize) {
        require(prices[assetIndex] > 0, "DEX: Invalid asset index");
        require(leverage > 0 && leverage <= 10, "DEX: Invalid leverage");
        // Mock position size calculation
        positionSize = (collateralAmount * uint256(leverage) * 1e18) / prices[assetIndex];
        return positionSize;
    }

    // Admin function to update mock prices (for testing different scenarios)
    function setPrice(uint16 assetIndex, uint256 newPrice) external {
        prices[assetIndex] = newPrice;
    }
}

