        uint64 total;
        uint64 hold;
        uint64 entryNtl;
    }

    struct UserVaultEquity {
        uint64 equity;
    }

    struct Withdrawable {
        uint64 withdrawable;
    }

    struct Delegation {
        address validator;
        uint64 amount;
        uint64 lockedUntilTimestamp;
    }

    struct DelegatorSummary {
        uint64 delegated;
        uint64 undelegated;
        uint64 totalPendingWithdrawal;
        uint64 nPendingWithdrawals;
    }

    // Mock storage
    mapping(address => mapping(uint16 => Position)) public position;
    mapping(address => mapping(uint64 => SpotBalance)) public spotBalance;
    mapping(address => mapping(address => UserVaultEquity))
        public userVaultEquity;
    mapping(address => Withdrawable) public withdrawable;
    mapping(address => Delegation[]) public delegations;
    mapping(address => DelegatorSummary) public delegatorSummary;
    mapping(uint16 => uint64) public markPx;
    mapping(uint16 => uint64) public oraclePx;
    mapping(uint32 => uint64) public spotPx;
    uint64 private mockL1BlockNumber;

    // Setter functions for testing
    function setPosition(
        address user,
        uint16 perp,
        Position memory pos
    ) external {
        position[user][perp] = pos;
    }

    function setSpotBalance(
        address user,
        uint64 token,
        SpotBalance memory bal
    ) external {
        spotBalance[user][token] = bal;
    }

    function setUserVaultEquity(
        address user,
        address vault,
        UserVaultEquity memory equity
    ) external {
        userVaultEquity[user][vault] = equity;
    }

    function setWithdrawable(
        address user,
        Withdrawable memory withdrawable_
    ) external {
        withdrawable[user] = withdrawable_;
    }

    function setDelegations(
        address user,
        Delegation[] memory delegations_
    ) external {
        delete delegations[user];
        for (uint i = 0; i < delegations_.length; i++) {
            delegations[user].push(delegations_[i]);
        }
    }

    function setDelegatorSummary(
        address user,
        DelegatorSummary memory summary
    ) external {
        delegatorSummary[user] = summary;
    }

    function setMarkPx(uint16 index, uint64 price) external {
        markPx[index] = price;
    }

    function setOraclePx(uint16 index, uint64 price) external {
        oraclePx[index] = price;
    }

    function setSpotPx(uint32 index, uint64 price) external {
        spotPx[index] = price;
    }

    function setL1BlockNumber(uint64 blockNumber) external {
        mockL1BlockNumber = blockNumber;
    }

    function l1BlockNumber() external view returns (uint64) {
        return mockL1BlockNumber;
    }
}

