    function closePositions(
        address holder,
        uint64 usdcAmount
    ) external returns (uint16[] memory indices, bool[] memory isBuy, uint64[] memory sz) {
        // Mock implementation - distribute according to allocations
        indices = new uint16[](3);
        isBuy = new bool[](3);
        sz = new uint64[](3);

        indices[0] = 0; // BTC
