    function getTradeHistory() external view returns (Trade[] memory) {
        return new Trade[](0); // Mock empty history
    }

    function getBalance() external view returns (uint256) {
        return balances[msg.sender];
    }

    function getHoldings() external view returns (Holding[] memory) {
        return new Holding[](0); // Mock empty holdings
    }

    function getOwner() external view returns (address) {
        return proxyOwner;
    }

    function getCoinType() external pure returns (CoinType) {
        return CoinType.MAJOR;
    }

    function getPositionDirection() external pure returns (PositionDirection) {
        return PositionDirection.LONG;
    }

    function getLeverage() external pure returns (uint32) {
        return LEVERAGE;
    }
}

